            bend = (y >= 4) ? bl[1] : 0.0;
            endow -= bend;
            budget = Math.max(0.0, inc - over - bspend);
            ng = (y === 5) ? C.NG[d.nextgen] : [0.0, 0.0, 0.0, 0.0];
            ngspend = Math.min(budget, ng[0]);
            budget -= ngspend;
            foc = C.FOC[d.focus];
            lg = C.LEG[d.legacy];
            if (y === 1 || d.focus === 'scatter') { oldsh = 1.0; }
            else { oldsh = (y === 2) ? lg[0] : lg[1]; }
            old = budget * oldsh;
            pool = budget - old;
            mea = C.MEA[d.measure];
            meas = pool * mea[0];
            grants = pool - meas;
            eff = foc[0] * C.BRD[d.board][1] * C.FRM[d.form][0] * C.SEL[d.select][1] * mea[1] * cri[2];
            if (y === 5) { eff *= C.REN[d.renewal][0]; }
            if (y === 2) { eff *= lg[2]; }
            if (y === 1) { eff = 0.0; }
            outc = old * C.OLD_EFF / 100.0 + grants * eff / 100.0 + (bspend + bend) * bl[2] / 100.0;
            if (d.nextgen === 'junior') { outc += ngspend * eff * ng[1] / 100.0; }
            else if (d.nextgen === 'seat') { outc += ngspend * C.NG_SEAT_EFF / 100.0; }
            if (y >= 3 && d.conflict === 'approve') { lrent = 1.0; }
            if (y === 5 && d.crisis === 'sell') { lsell = 1.0; }
            outTotal += outc;
            spent += over + meas + bspend + bend + old + grants + ngspend;
            given += old + grants + ngspend + bspend + bend;
        }
        var legal = lrent + lsell;
        d = setting(dec, C.YEARS);
        var H = C.H0 + C.FRM[d.form][1] + C.SEL[d.select][2] + C.MEA[d.measure][2] + C.LEG[d.legacy][3] + C.CRI[d.crisis][3];
        var P = C.P0 + C.FOC[d.focus][1] + C.BRD[d.board][2] + C.LEG[d.legacy][4] + C.CNF[d.conflict][1] + C.COM[d.comms][1];
        P += C.BLD[d.building][3] + C.NG[d.nextgen][2] + C.CRI[d.crisis][4] + C.REN[d.renewal][1];
        var G = C.G0 + C.FOC[d.focus][2] + C.BRD[d.board][3] + C.SEL[d.select][3] + C.CNF[d.conflict][2] + C.COM[d.comms][2];
        G += C.BLD[d.building][4] + C.NG[d.nextgen][3] + C.CRI[d.crisis][5] + C.REN[d.renewal][2];
        H = clamp(H, 0.0, 100.0);
        P = clamp(P, 0.0, 100.0);
        G = clamp(G, 0.0, 100.0);
        var cpo = outTotal > 0 ? spent * 1000.0 / outTotal : 999999.0;
        return { E: outTotal, cpo: cpo, spent: spent, given: given, endow: endow, H: H, P: P, G: G, legal: legal, sev: C.CAP_LEGAL * legal };
    }

    class ElLegado2307Adapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'El Legado';
            this.version = '1.0.0';
            this.ROUNDS = [
                { panel: 'roundPanel1', nameKey: 'r1_name', briefKey: 'r1_brief' },
                { panel: 'roundPanel2', nameKey: 'r2_name', briefKey: 'r2_brief' },
                { panel: 'roundPanel3', nameKey: 'r3_name', briefKey: 'r3_brief' },
                { panel: 'roundPanel4', nameKey: 'r4_name', briefKey: 'r4_brief' }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    rounds: [],
                    periods: [],
                    sevCum: 0,
                    dec: {},
                    scoreHistory: [],
                    performance: { overallScore: 0 },
                    performanceTier: 'beginner'
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {};
            }
            this._syncControlsFromDecisions(state);
            this._updateBriefing(state);
        }

        _syncControlsFromDecisions(state) {
            var raw = (state && state.decisions) || {};
            var saved = (state && state.domainState && state.domainState.dec) || {};
            var set = function(id, val) {
                var el = document.getElementById(id);
                if (el && val !== undefined && val !== null) { el.value = String(val); }
            };
            var r, d, keys, i;
            for (r = 1; r <= NR; r++) {
                d = raw['round' + r] || saved['round' + r];
                if (!d) { continue; }
                keys = Object.keys(CTRL['round' + r]);
                for (i = 0; i < keys.length; i++) { set('r' + r + '_' + keys[i], d[keys[i]]); }
            }
        }

        _t(key, vars) {
            return window.mySimulation ? window.mySimulation.t(key, vars) : key;
        }

        _cl(key, fallback) {
            var s = this._t(key);
            return s === key ? fallback : s;
        }

        _lang() {
            return (window.mySimulation && window.mySimulation.language === 'en') ? 'en' : 'es';
        }

        // Spanish format in es (point thousands, comma decimals); English format in en.
        _fmtNum(v, dec) {
            var n = Number(v) || 0;
            var neg = n < 0;
            var f = Math.abs(n).toFixed(dec);
            var parts = f.split('.');
            var s = parts[0];
            var out = '';
            var th = this._lang() === 'en' ? ',' : '.';
            var dp = this._lang() === 'en' ? '.' : ',';
            while (s.length > 3) { out = th + s.slice(-3) + out; s = s.slice(0, -3); }
            out = s + out;
            if (parts.length > 1) { out = out + dp + parts[1]; }
            return (neg && Number(f) !== 0 ? '−' : '') + out;
        }

        // Euros without decimals: 8.037 € in es, €8,037 in en.
        _fmtMoney(v) {
            var n = Math.round(Number(v) || 0);
            if (this._lang() === 'en') { return (n < 0 ? '−' : '') + '€' + this._fmtNum(Math.abs(n), 0); }
            return (n < 0 ? '−' : '') + this._fmtNum(Math.abs(n), 0) + ' €';
        }

        // Thousands of euros as millions with two decimals: 4,53 M€ in es, €4.53m in en.
        _fmtM(vk) {
            var m = (Number(vk) || 0) / 1000.0;
            if (this._lang() === 'en') { return '€' + this._fmtNum(m, 2) + 'm'; }
            return this._fmtNum(m, 2) + ' M€';
        }

        _updateBriefing(state) {
            var cur = (state && state.currentPeriod) || 1;
            var maxP = (state && state.maxPeriods) || this.ROUNDS.length;
            var done = (state && state.history) ? state.history.length : 0;
            var finished = done >= maxP || cur > this.ROUNDS.length;
            var i, panel;
            for (i = 0; i < this.ROUNDS.length; i++) {
                panel = document.getElementById(this.ROUNDS[i].panel);
                if (panel) { panel.style.display = (!finished && (i + 1) === cur) ? 'block' : 'none'; }
            }
            var actions = document.getElementById('actionsRow');
            if (actions) { actions.style.display = finished ? 'none' : 'flex'; }
            var idx = Math.min(cur, this.ROUNDS.length) - 1;
            var nameEl = document.getElementById('roundName');
            if (nameEl) { nameEl.textContent = finished ? this._t('round_done') : this._t(this.ROUNDS[idx].nameKey); }
            var briefEl = document.getElementById('briefingText');
            if (briefEl) { briefEl.innerHTML = finished ? this._t('brief_done') : this._t(this.ROUNDS[idx].briefKey); }
            this._renderDynamic(state);
        }

        _renderDynamic(state) {
            var ds = (state && state.domainState) || {};
            var ps = ds.periods || [];
            var rounds = ds.rounds || [];
            var sEl = document.getElementById('semesterText');
            if (sEl) { sEl.innerHTML = ps.length ? this._periodHtml(ds, ps[ps.length - 1]) : this._t('sem_pending'); }
            var fbEl = document.getElementById('feedbackText');
            if (fbEl) {
                fbEl.classList.remove('ea2307-warn');
                var last = rounds.length ? rounds[rounds.length - 1] : null;
                if (!last) { fbEl.innerHTML = this._t('feedback_empty'); }
                else {
                    fbEl.innerHTML = this._feedbackHtml(ds, last);
                    if (last.verdictKey !== 'ok') { fbEl.classList.add('ea2307-warn'); }
                }
            }
        }

        _periodHtml(ds, q) {
            var html = this._t('sem_body', { out: this._fmtNum(q.E, 1), cpo: this._fmtMoney(q.cpo), given: this._fmtM(q.given), spent: this._fmtM(q.spent), endow: this._fmtM(q.endow) });
            html += '<span class="ea2307-cases">' + this._t('s_idx', { h: this._fmtNum(q.H, 0), p: this._fmtNum(q.P, 0), g: this._fmtNum(q.G, 0) }) + '</span>';
            if (q.legal > 0) { html += '<span class="ea2307-reveal">' + this._t('s_legal', { n: this._fmtNum(q.legal, 0) }) + '</span>'; }
            var keys = ds.capKeys || [];
            var i;
            for (i = 0; i < keys.length; i++) {
                html += '<span class="ea2307-reveal">' + this._t(keys[i], { cap: this._fmtNum(ds.cap || 0, 1) }) + '</span>';
            }
            return html;
        }

        _feedbackHtml(ds, r) {
            var v = { pts: this._fmtNum(Math.round(r.pts * 10) / 10, 1), max: this._fmtNum(C.W_ROUND[r.period - 1], 0) };
            return '<strong>' + this._t('fb_points', v) + '</strong> ' + this._t('fb_r' + r.period + '_' + r.verdictKey, v);
        }

        _readSelect(id, allowed) {
            var el = document.getElementById(id);
            if (!el) { return null; }
            var val = String(el.value);
            if (allowed.indexOf(val) === -1) { return null; }
            return val;
        }

        validateDecisions(decisions) {
            var sim = window.mySimulation;
            var state = sim && sim.state ? sim.state : { currentPeriod: 1, history: [] };
            var period = state.currentPeriod || 1;
            var done = state.history ? state.history.length : 0;
            var warn = function(key) {
                sim.uiManager.showNotification(sim.t(key), 'warning');
                return false;
            };
            if (done >= this.ROUNDS.length || period > this.ROUNDS.length) { return warn('warn_finished'); }
            var rk = 'round' + period;
            var keys = Object.keys(CTRL[rk]);
            var out = {};
            var i, val;
            for (i = 0; i < keys.length; i++) {
                val = this._readSelect('r' + period + '_' + keys[i], CTRL[rk][keys[i]]);
                if (!val) { return warn('warn_r' + period); }
                out[keys[i]] = val;
            }
            decisions[rk] = out;
            return true;
        }

        calculateResults(state) {
            var out = this._computeRound(state);
            var self = this;
            setTimeout(function() { self._updateBriefing(window.mySimulation.state); }, 400);
            return out;
        }

        // Round model. Every decision is re-evaluated from the decision history, so a resubmit is idempotent.
        _computeRound(state) {
            var ds = state.domainState;
            var raw = state.decisions || {};
            var period = state.currentPeriod || 1;
            var saved = ds.dec || {};
            var d = {};
            var k;
            for (k = 1; k <= period; k++) {
                if (raw['round' + k]) { d['round' + k] = raw['round' + k]; }
                else if (k < period && saved['round' + k]) { d['round' + k] = saved['round' + k]; }
            }
            ds.dec = JSON.parse(JSON.stringify(d));
            var rounds = [];
            var periods = [];
            var total = 0.0;
            var cap = 100.0;
            var r, known, q, rub, W, oe, oc, oh, op, og, pts;
            for (r = 1; r <= period; r++) {
                known = knownUpTo(d, r);
                q = evaluate(known);
                q.t_round = r;
                rub = this._rubric(known, r);
                W = C.W_OUT[r - 1];
                oe = W * C.W_E * clamp((q.E - C.E_LO) / C.E_SPAN, 0.0, 1.0);
                oc = W * C.W_C * clamp((C.C_HI - q.cpo) / C.C_SPAN, 0.0, 1.0);
                oh = W * C.W_H * clamp((q.H - C.H_LO) / C.H_SPAN, 0.0, 1.0);
                op = W * C.W_P * clamp((q.P - C.P_LO) / C.P_SPAN, 0.0, 1.0);
                og = W * C.W_G * q.G / 100.0;
                pts = rub + oe + oc + oh + op + og;
                total += pts;
                cap = 100.0;
                if (q.sev > 0) { cap = Math.max(C.CAP_FLOOR, C.CAP_BASE - q.sev); }
                periods.push(q);
                rounds.push({ period: r, rub: rub, oe: oe, oc: oc, oh: oh, op: op, og: og, pts: pts, verdictKey: this._verdict(known, r) });
            }
            var last = periods[periods.length - 1];
            ds.rounds = rounds;
            ds.periods = periods;
            ds.sevCum = last.sev;
            ds.total = total;
            ds.cap = cap;
            var score = this._composite(ds);
            ds.capKeys = [];
            if (last.legal > 0 && total > cap) { ds.capKeys.push('cap_legal'); }
            ds.performance = { overallScore: score };
            ds.performanceTier = this._tier(score);
            ds.scoreHistory = (ds.scoreHistory || []).slice(0, period - 1);
            ds.scoreHistory[period - 1] = score;
            ds.scoreHistory.length = period;
            return {
                period: period,
                roundPoints: Math.round(rounds[period - 1].pts * 10) / 10,
                out: Math.round(last.E * 10) / 10,
                cpo: Math.round(last.cpo),
                given: Math.round(last.given),
                health: Math.round(last.H),
                coh: Math.round(last.P),
                gov: Math.round(last.G),
                score: score,
                overallScore: score
            };
        }

        _rubric(dec, r) {
            var P = C.PTS;
            var d = dec['round' + r];
            var keys = Object.keys(CTRL['round' + r]);
            var s = 0, i;
            for (i = 0; i < keys.length; i++) { s += P[keys[i] + r][d[keys[i]]]; }
            return s;
        }

        _verdict(dec, r) {
            var d = dec['round' + r];
            var order = VORDER[r];
            var i;
            for (i = 0; i < order.length; i++) {
                if (d[order[i][0]] === order[i][1]) { return order[i][1]; }
            }
            return 'ok';
        }

        _composite(ds) {
            var total = Math.min((ds && typeof ds.cap === 'number') ? ds.cap : 100, (ds && ds.total) || 0);
            return Math.max(0, Math.min(100, Math.round(total)));
        }

        _tier(score) {
            if (score >= 75) { return 'excellent'; }
            if (score >= 55) { return 'good'; }
            return 'beginner';
        }

        setupUI(uiManager) {
            var self = this;
            var lastP = function(ds) { var ps = (ds && ds.periods) || []; return ps.length ? ps[ps.length - 1] : null; };
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.performance.overallScore', function(v) { return (typeof v === 'number') ? String(v) : '0'; });
            uiManager.bind('outDisplay', 'domainState', function(ds) { var q = lastP(ds); return q ? self._fmtNum(q.E, 1) : '—'; });
            uiManager.bind('cpoDisplay', 'domainState', function(ds) { var q = lastP(ds); return q ? self._fmtMoney(q.cpo) : '—'; });
            uiManager.bind('givenDisplay', 'domainState', function(ds) { var q = lastP(ds); return q ? self._fmtM(q.given) : '—'; });
            uiManager.bind('healthDisplay', 'domainState', function(ds) { var q = lastP(ds); return q ? self._fmtNum(q.H, 0) : '—'; });
            uiManager.bind('cohDisplay', 'domainState', function(ds) { var q = lastP(ds); return q ? self._fmtNum(q.P, 0) : '—'; });
            uiManager.bind('govDisplay', 'domainState', function(ds) { var q = lastP(ds); return q ? self._fmtNum(q.G, 0) : '—'; });
        }

        getChartConfig() {
            var t = this._t.bind(this);
            var sp = t('s_shortp');
            return {
                qualityChart: {
                    type: 'bar',
                    data: {
                        labels: [sp + '1', sp + '2', sp + '3', sp + '4'],
