                            { label: t('chart_health'), data: [0, 0, 0, 0], backgroundColor: '#23374d', borderWidth: 0 },
                            { label: t('chart_gov'), data: [0, 0, 0, 0], backgroundColor: '#1f6b4f', borderWidth: 0 }
                        ]
                    },
                    options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: true, labels: { color: '#2b3440' } } }, scales: { y: { min: 0, max: 100, ticks: { color: '#2b3440' } }, x: { ticks: { color: '#2b3440' } } } }
                }
            };
        }

        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var ps = ds.periods || [];
            var f = [0, 0, 0, 0];
            var c = [0, 0, 0, 0];
            var sp = this._t('s_shortp');
