                { key: 'results.cpo', label: 'Cost per outcome', i18nKey: 'col_cpo', formatter: function(v) { return self._fmtMoney(v); } },
                { key: 'results.given', label: 'To programmes', i18nKey: 'col_given', formatter: function(v) { return self._fmtM(v); } },
                { key: 'results.health', label: 'Grantee health', i18nKey: 'col_health', formatter: function(v) { return self._fmtNum(v, 0); } },
                { key: 'results.coh', label: 'Cohesion', i18nKey: 'col_coh', formatter: function(v) { return self._fmtNum(v, 0); } },
                { key: 'results.gov', label: 'Governance', i18nKey: 'col_gov', formatter: function(v) { return self._fmtNum(v, 0); } },
                { key: 'results.score', label: 'Score', i18nKey: 'col_score' }
            ];
        }

        getHint(state, results) {
            var ds = state.domainState || {};
            var r = (ds.rounds || [])[(results.period || 1) - 1];
            if (!r) { return null; }
            return this._t('hint_r' + r.period + '_' + r.verdictKey);
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) { return {}; }
            var ds = window.mySimulation.state.domainState;
            var ps = ds.periods || [];
            var score = this._composite(ds);
            var performance = 'Beginner';
            if (score >= 55) { performance = 'Good'; }
            if (score >= 75) { performance = 'Excellent'; }
            var q = ps.length ? ps[ps.length - 1] : { E: 0, cpo: 0, spent: 0, given: 0, endow: 0, H: 0, P: 0, G: 0, legal: 0, sev: 0 };
            var insights = [];
            insights.push(q.E >= C.E_OK ? this._t('insight_e_ok') : this._t('insight_e_bad'));
            insights.push(q.cpo <= C.C_OK ? this._t('insight_c_ok') : this._t('insight_c_bad'));
            insights.push(q.H >= C.H_OK ? this._t('insight_h_ok') : this._t('insight_h_bad'));
            insights.push(q.P >= C.P_OK ? this._t('insight_p_ok') : this._t('insight_p_bad'));
            insights.push(q.G >= C.G_OK ? this._t('insight_g_ok') : this._t('insight_g_bad'));
            insights.push((ds.sevCum || 0) > 0 ? this._t('insight_law_bad') : this._t('insight_law_ok'));
            insights.push(this._t('insight_next'));
            return {
                composite: score,
                overallScore: score,
                totalScore: score,
                score: score,
                outcomes: q.E,
                cpo: q.cpo,
                given: q.given,
                spent: q.spent,
                endow: q.endow,
                health: q.H,
                coh: q.P,
                gov: q.G,
                sev: ds.sevCum || 0,
                rounds: (ds.scoreHistory || []).length,
                performance: performance,
                performanceKey: performance.toLowerCase(),
                performanceLabel: this._cl('grade_' + performance.toLowerCase(), performance),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
