                + '<div class="ea2307-cm-kpi">' + this._t('cm_kpi_cpo') + '<strong>' + this._fmtMoney(s.cpo) + '</strong></div>'
                + '<div class="ea2307-cm-kpi">' + this._t('cm_kpi_given') + '<strong>' + this._fmtM(s.given) + '</strong></div>'
                + '<div class="ea2307-cm-kpi">' + this._t('cm_kpi_endow') + '<strong>' + this._fmtM(s.endow) + '</strong></div>'
                + '</div>'
                + '<div class="ea2307-cm-debrief">' + this._t('cm_debrief') + '</div>'
                + '<ul class="ea2307-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getTranslations() {
            return {
        es: {
